Patron Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Patron_Portal_Container", "Patron Portal") {
    Component("UIPresentationLayer", "UI Presentation Layer", "React / Tailwind CSS", "Powers server-rendered UI for performance and WCAG 2.1 AA accessibility.")
    Component("BFFRouteHandlerLayer", "BFF / Route Handler Layer", "Next.js Node.js runtime", "Isolates sensitive session tokens and handles proxied requests with OIDC tokens.")
    Component("PatronPortalContainer", "Patron Portal Container", "Next.js", "Secure self-service web interface enabling library patrons to catalogue items, manage accounts, and handle circulation tasks.")
}

Rel("UIPresentationLayer", "BFFRouteHandlerLayer", "Internal React Server Actions", "Direct IPC")
Rel("BFFRouteHandlerLayer", "PatronPortalContainer", "Serves application logic and handles routing", "")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Envoy_Proxy_Router, "Envoy Proxy Router", "Envoy Proxy, xDS dynamic control planes", "Handles routing, ingress security, gRPC-web support, and low memory footprint traffic management.")
    Component(Rate_Limiting_Module, "Rate Limiting Module", "Envoy Proxy Rate Limit Service", "Enforces strict rate-limiting policies for incoming public and academic library requests.")
    Component(Security_Wasm_Filter, "Security & Wasm Filter", "WebAssembly (Wasm) filters, TLS 1.3", "Executes custom security checks, handles mTLS certificate rotation integration with HashiCorp Vault, and validates EU-only data residency constraints.")
}

Rel(Envoy_Proxy_Router, Rate_Limiting_Module, "Inspects incoming requests against rate-limiting rules")
Rel(Envoy_Proxy_Router, Security_Wasm_Filter, "Passes ingress traffic through Wasm filters for inspection and token handling")
Rel(Security_Wasm_Filter, Search_Catalogue_Service, "Routes queries via gRPC with mTLS", "gRPC / mTLS")
@enduml

HashiCorp Vault.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the HashiCorp Vault container

Container_Boundary(vault_container, "HashiCorp Vault") {
    Component(CoreHttpApiLayer, "Core/HTTP API Layer", "HashiCorp Vault Go-based API engine", "Handles secure REST/HTTPS requests, policy enforcement, and core secrets management operations.")
    Component(IntegratedRaftStorageBackend, "Integrated Raft Storage Backend", "Raft Consensus Algorithm Storage", "Persists encrypted data locally within the container ensuring strict EU data residency compliance.")
    Component(VaultAgentSidecar, "Vault Agent Sidecar", "HashiCorp Vault Agent", "Provides client-side caching, automated authentication, and transit security via Unix Domain Sockets or localhost TCP.")
}

Rel(VaultAgentSidecar, CoreHttpApiLayer, "Communicates via HTTPS (REST) over mTLS on Port 8200", "HTTPS / mTLS")
Rel(CoreHttpApiLayer, IntegratedRaftStorageBackend, "Persists encrypted data using Raft internal RPC over TLS", "Raft RPC / TLS")

@enduml
